-- Databáza zložiek v1.0 (225 typov, 3 511 variantov zápisu) + skóre produktov.
-- Spustiť po migrácii 20261126010000_ingredient_scores.sql a po importe produktov. Opakovateľné.
begin;

insert into public.ingredients (slug, name_sk, category, classification, sensitivity_flags, is_artificial_additive, is_added_sugar, what_it_is, score, occurrences, methodology_version) values
  ('kuracie-cerstve', 'Kuracie mäso (čerstvé)', 'maso', 'pomenovana', '{kuracie}'::text[], false, false, 'Čerstvé kuracie mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Pozor: čerstvé mäso obsahuje asi 70 % vody, takže po vysušení ho v granule zostane podstatne menej, než ukazuje percento na obale. Kuracie je kvalitné mäso, ale patrí medzi častejšie alergény u psov.', 100, 213, '1.0'),
  ('kuracie-susene', 'Kuracie mäso (sušené)', 'maso', 'pomenovana', '{kuracie}'::text[], false, false, 'Sušené (dehydrované) kuracie mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse. Kuracie je kvalitné mäso, ale patrí medzi častejšie alergény u psov.', 100, 143, '1.0'),
  ('morcacie-susene', 'Morčacie mäso (sušené)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Sušené (dehydrované) morčacie mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse.', 100, 52, '1.0'),
  ('ine-strukoviny', 'Šošovica / cícer / fazuľa', 'strukovina', 'pomenovana', '{strukoviny}'::text[], false, false, 'Strukovina – zdroj energie, vlákniny a rastlinnej bielkoviny.', 72, 174, '1.0'),
  ('hrach', 'Hrach / hrášok', 'strukovina', 'pomenovana', '{strukoviny}'::text[], false, false, 'Strukovina – zdroj energie, vlákniny a rastlinnej bielkoviny. Bežná náhrada obilia v krmivách „bez obilnín“.', 70, 690, '1.0'),
  ('kuracie-vnutor', 'Kuracie vnútornosti', 'maso', 'pomenovana', '{kuracie}'::text[], false, false, 'Kuracie vnútornosti (pečeň, srdce, žalúdky…) – pomenované a výživovo veľmi hodnotné, prirodzene bohaté na vitamíny a minerály. Kuracie je kvalitné mäso, ale patrí medzi častejšie alergény u psov.', 97, 74, '1.0'),
  ('sled-susene', 'Sleď mäso (sušené)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Sušené (dehydrované) sleď mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse.', 100, 24, '1.0'),
  ('kuracie-tuk', 'Kuracie tuk / olej', 'tuk_olej', 'pomenovana', '{kuracie}'::text[], false, false, 'Kuracie tuk / olej – pomenovaný zdroj energie a mastných kyselín. Kuracie je kvalitné mäso, ale patrí medzi častejšie alergény u psov.', 85, 308, '1.0'),
  ('vajcia', 'Vajcia', 'maso', 'pomenovana', '{}'::text[], false, false, 'Vysoko stráviteľná živočíšna bielkovina s výbornou biologickou hodnotou.', 92, 436, '1.0'),
  ('platesa-cerstve', 'Platesa mäso (čerstvé)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Čerstvé platesa mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Pozor: čerstvé mäso obsahuje asi 70 % vody, takže po vysušení ho v granule zostane podstatne menej, než ukazuje percento na obale.', 100, 11, '1.0'),
  ('sled-tuk', 'Sleď tuk / olej', 'tuk_olej', 'pomenovana', '{}'::text[], false, false, 'Sleď tuk / olej – pomenovaný zdroj energie a mastných kyselín.', 90, 15, '1.0'),
  ('bylinky', 'Bylinky a koreniny', 'prisada', 'pomenovana', '{}'::text[], false, false, 'Bylinky a koreniny pridané v malom množstve pre chuť alebo podporu trávenia. Na celkovú výživu majú malý vplyv.', 88, 1317, '1.0'),
  ('hrachove-frakcie', 'Hrachová bielkovina / škrob / vláknina', 'strukovina', 'spracovana', '{strukoviny}'::text[], false, false, 'Časť hrachu oddelená pri spracovaní. Hrachová bielkovina lacne zvyšuje obsah bielkovín na etikete, škrob slúži ako pojivo. Ak je ich v zložení viac, môžu „rozdeliť“ hrach, aby nebol na prvom mieste.', 55, 338, '1.0'),
  ('riasy', 'Morské riasy / spirulina', 'prisada', 'pomenovana', '{}'::text[], false, false, 'Prírodný zdroj minerálov, jódu a pri niektorých riasach aj omega-3 mastných kyselín.', 88, 363, '1.0'),
  ('zelenina', 'Zelenina', 'zelenina_ovocie', 'pomenovana', '{}'::text[], false, false, 'Zelenina dodáva vlákninu, vitamíny a antioxidanty. Zvyčajne je jej v granulách malé množstvo.', 90, 1018, '1.0'),
  ('bylinky2', 'Bylinky, čaj a rastlinné extrakty', 'prisada', 'pomenovana', '{}'::text[], false, false, 'Bylinky a rastlinné extrakty pridané v malom množstve pre chuť alebo podporu trávenia a imunity.', 88, 360, '1.0'),
  ('ovocie', 'Ovocie a bobuľoviny', 'zelenina_ovocie', 'pomenovana', '{}'::text[], false, false, 'Ovocie a bobuľoviny sú zdrojom vitamínov a antioxidantov. V granulách býva v malom množstve.', 90, 1462, '1.0'),
  ('morcacie-vnutor', 'Morčacie vnútornosti', 'maso', 'pomenovana', '{}'::text[], false, false, 'Morčacie vnútornosti (pečeň, srdce, žalúdky…) – pomenované a výživovo veľmi hodnotné, prirodzene bohaté na vitamíny a minerály.', 97, 17, '1.0'),
  ('prebiotika', 'Prebiotiká (čakanka, inulín, FOS, MOS)', 'vlaknina', 'pomenovana', '{}'::text[], false, false, 'Látky, ktoré slúžia ako potrava pre prospešné črevné baktérie a podporujú zdravé trávenie a imunitu.', 92, 1850, '1.0'),
  ('rastlinne-oleje-semena', 'Rastlinné oleje a semená (slnečnica, repka, konope…)', 'tuk_olej', 'pomenovana', '{}'::text[], false, false, 'Konkrétne pomenovaný rastlinný olej alebo semeno – zdroj energie a mastných kyselín.', 75, 439, '1.0'),
  ('hovadzie-cerstve', 'Hovädzie mäso (čerstvé)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Čerstvé hovädzie mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Pozor: čerstvé mäso obsahuje asi 70 % vody, takže po vysušení ho v granule zostane podstatne menej, než ukazuje percento na obale.', 100, 38, '1.0'),
