  ('treska-tuk', 'Treska tuk / olej', 'tuk_olej', 'pomenovana', '{}'::text[], false, false, 'Treska tuk / olej – pomenovaný zdroj energie a mastných kyselín.', 88, 4, '1.0'),
  ('kuracie-muck', 'Kuracie múčka', 'maso', 'spracovana', '{kuracie}'::text[], false, false, 'Múčka z kuracie mäsa – mäso (často aj s kosťami) usušené a zomleté. Pomenovaný a koncentrovaný zdroj bielkovín, no kvalita závisí od toho, aké časti zvieraťa sa použili. Kuracie je kvalitné mäso, ale patrí medzi častejšie alergény u psov.', 40, 71, '1.0'),
  ('zemiaky', 'Zemiaky / zemiakové vločky', 'zelenina_ovocie', 'pomenovana', '{}'::text[], false, false, 'Zdroj energie (škrobu), bežná náhrada obilia v krmivách bez obilnín.', 70, 594, '1.0'),
  ('batat', 'Batáty (sladké zemiaky)', 'zelenina_ovocie', 'pomenovana', '{}'::text[], false, false, 'Zdroj energie a vlákniny s pomalším uvoľňovaním cukrov, dobre stráviteľný.', 85, 190, '1.0'),
  ('jahnacie-maso', 'Jahňacie mäso', 'maso', 'pomenovana', '{}'::text[], false, false, 'Jahňacie mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín.', 100, 113, '1.0'),
  ('hovadzie-susene', 'Hovädzie mäso (sušené)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Sušené (dehydrované) hovädzie mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse.', 100, 21, '1.0'),
  ('hovadzie-tuk', 'Hovädzie tuk / olej', 'tuk_olej', 'pomenovana', '{}'::text[], false, false, 'Hovädzie tuk / olej – pomenovaný zdroj energie a mastných kyselín.', 85, 96, '1.0'),
  ('hovadzie-vnutor', 'Hovädzie vnútornosti', 'maso', 'pomenovana', '{}'::text[], false, false, 'Hovädzie vnútornosti (pečeň, srdce, žalúdky…) – pomenované a výživovo veľmi hodnotné, prirodzene bohaté na vitamíny a minerály.', 97, 8, '1.0'),
  ('vlaknina-rastlinna', 'Rastlinná vláknina', 'vlaknina', 'nespecifikovana', '{}'::text[], false, false, 'Vláknina z rastlín bez bližšieho určenia – podporuje trávenie a pocit sýtosti.', 70, 214, '1.0'),
  ('prirodne-antioxidanty', 'Prírodné antioxidanty (tokoferoly, rozmarín)', 'prisada', 'pomenovana', '{}'::text[], false, false, 'Prírodné látky, ktoré chránia tuky v granulách pred žltnutím. Lepšia alternatíva syntetických konzervantov.', 90, 87, '1.0'),
  ('losos-cerstve', 'Losos mäso (čerstvé)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Čerstvé losos mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Pozor: čerstvé mäso obsahuje asi 70 % vody, takže po vysušení ho v granule zostane podstatne menej, než ukazuje percento na obale.', 100, 37, '1.0'),
  ('bravcove-vnutor', 'Bravčové vnútornosti', 'maso', 'pomenovana', '{}'::text[], false, false, 'Bravčové vnútornosti (pečeň, srdce, žalúdky…) – pomenované a výživovo veľmi hodnotné, prirodzene bohaté na vitamíny a minerály.', 97, 23, '1.0'),
  ('kuracie-maso', 'Kuracie mäso', 'maso', 'pomenovana', '{kuracie}'::text[], false, false, 'Kuracie mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Kuracie je kvalitné mäso, ale patrí medzi častejšie alergény u psov.', 100, 196, '1.0'),
  ('psenica', 'Pšenica', 'obilnina', 'pomenovana', '{obilniny}'::text[], false, false, 'Obilnina, lacný zdroj energie a pojivo. Obsahuje lepok – niektoré psy na ňu reagujú citlivo (trávenie, koža).', 50, 309, '1.0'),
  ('kukurica', 'Kukurica', 'obilnina', 'pomenovana', '{obilniny}'::text[], false, false, 'Obilnina, lacný zdroj energie (škrobu) a pojivo granúl. Nutrične slabšia ako mäso; ak je vysoko v zložení, granula je postavená skôr na obilí ako na mäse.', 55, 912, '1.0'),
  ('hydina-bielkov', 'Hydina (bielkov)', 'maso', 'spracovana', '{kuracie}'::text[], false, false, 'Hydina bez uvedenia druhu (kura, morka, kačica…). Je to živočíšny zdroj, ale presné zviera nevieme – pri alergii na kuracie to nie je možné vylúčiť.', 70, 277, '1.0'),
  ('zivocisny-tuk-nespecifikovany', 'Živočíšny tuk (bez uvedenia zvieraťa)', 'tuk_olej', 'nespecifikovana', '{}'::text[], false, false, 'Tuk zo zvierat bez uvedenia druhu. Dodáva energiu a chuť, ale nevieme, odkiaľ pochádza.', 30, 386, '1.0'),
  ('hydrolyzat-nespecifikovany', 'Hydrolyzované bielkoviny (bez uvedenia zdroja)', 'zivocisny_vedlajsi_produkt', 'nespecifikovana', '{}'::text[], false, false, 'Bielkoviny rozložené na menšie časti – zlepšujú chuť a sú ľahšie stráviteľné. Nie je však uvedené, z čoho pochádzajú, takže sa nedá overiť pôvod ani vhodnosť pri alergii.', 40, 435, '1.0'),
  ('kukuricny-lepok', 'Kukuričný lepok / kukuričná bielkovina', 'obilnina', 'spracovana', '{obilniny}'::text[], false, false, 'Bielkovinová frakcia z kukurice, zvyšok po výrobe škrobu. Lacne zvyšuje číslo „bielkoviny“ na etikete, ale rastlinná bielkovina je pre psa menej hodnotná ako živočíšna.', 35, 283, '1.0'),
  ('ryza', 'Ryža', 'obilnina', 'pomenovana', '{obilniny}'::text[], false, false, 'Ľahko stráviteľný zdroj energie (sacharidov), vhodný aj pre citlivé trávenie.', 80, 918, '1.0'),
  ('bravcove-bielkov', 'Bravčové bielkovina', 'maso', 'spracovana', '{}'::text[], false, false, 'Bravčové bielkovina / proteín – koncentrovaný a pomenovaný živočíšny zdroj bielkovín (sušené a odtučnené mäso).', 90, 102, '1.0'),
  ('klby', 'Glukozamín / chondroitín / kolagén', 'prisada', 'pomenovana', '{}'::text[], false, false, 'Látky prirodzene sa vyskytujúce v chrupavkách. Pridávajú sa na podporu kĺbov.', 92, 1370, '1.0'),
  ('mineralne-latky', 'Minerálne látky', 'vitaminy_mineraly', 'nespecifikovana', '{}'::text[], false, false, 'Zmes minerálov (vápnik, fosfor, sodík…) potrebná pre kompletnú výživu. Bežné, ale bez bližšieho rozpisu.', 75, 958, '1.0'),
  ('hydina-tuk', 'Hydina (tuk)', 'tuk_olej', 'spracovana', '{kuracie}'::text[], false, false, 'Hydina bez uvedenia druhu (kura, morka, kačica…). Je to živočíšny zdroj, ale presné zviera nevieme – pri alergii na kuracie to nie je možné vylúčiť.', 78, 415, '1.0'),
  ('repna-duzina', 'Repná dužina / repné rezky', 'vlaknina', 'spracovana', '{}'::text[], false, false, 'Vláknina z cukrovej repy (cukor je odstránený). Podporuje trávenie a pevnú stolicu.', 75, 987, '1.0'),
  ('celuloza', 'Celulóza / lignocelulóza', 'vlaknina', 'spracovana', '{}'::text[], false, false, 'Nerozpustná vláknina (často z dreva). Pomáha pri sýtosti a tvorbe stolice, ale nemá výživovú hodnotu – vo väčšom množstve je to plnivo.', 50, 248, '1.0'),
  ('soja', 'Sója / sójová múka', 'strukovina', 'pomenovana', '{strukoviny}'::text[], false, false, 'Lacný rastlinný zdroj bielkovín. Zvyšuje číslo bielkovín na etikete, je častým alergénom a môže spôsobovať plynatosť.', 40, 263, '1.0'),
  ('kvasnice', 'Kvasnice / pivovarské kvasnice', 'prisada', 'pomenovana', '{}'::text[], false, false, 'Zdroj vitamínov skupiny B, bielkovín a látok podporujúcich imunitu. Zlepšujú aj chuť.', 85, 1275, '1.0'),
  ('losos-maso', 'Losos mäso', 'maso', 'pomenovana', '{}'::text[], false, false, 'Losos mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín.', 100, 86, '1.0'),
  ('losos-bielkov', 'Losos bielkovina', 'maso', 'spracovana', '{}'::text[], false, false, 'Losos bielkovina / proteín – koncentrovaný a pomenovaný živočíšny zdroj bielkovín (sušené a odtučnené mäso).', 90, 64, '1.0'),
