  ('glycerin', 'Glycerín / sorbitol', 'prisada', 'spracovana', '{}'::text[], false, false, 'Látka udržiavajúca vlhkosť a mäkkosť granúl. Pre výživu psa nemá význam.', 55, 46, '1.0'),
  ('skrob', 'Škrob (zemiakový, tapiokový…)', 'ine', 'spracovana', '{}'::text[], false, false, 'Čistý škrob – pojivo, ktoré drží granulu pokope, a lacný zdroj energie. Výživovo chudobný.', 55, 176, '1.0'),
  ('rastlinna-bielkovina-nespec', 'Rastlinná bielkovina (bez uvedenia zdroja)', 'ine', 'nespecifikovana', '{}'::text[], false, false, 'Bielkovina z rastlín bez uvedenia, z akých. Lacne zvyšuje obsah bielkovín na etikete; pre psa je menej hodnotná ako živočíšna.', 45, 82, '1.0'),
  ('cukor', 'Cukor / sladidlá', 'prisada', 'spracovana', '{}'::text[], false, true, 'Pridaný cukor alebo sladidlo – zlepšuje chuť, ale pes ho vo výžive nepotrebuje a prispieva k nadváhe a zubnému kameňu.', 10, 41, '1.0'),
  ('mliecne', 'Mlieko a mliečne výrobky', 'ine', 'pomenovana', '{}'::text[], false, false, 'Mliečne zložky zlepšujú chuť. Dospelé psy však laktózu často zle trávia.', 55, 25, '1.0'),
  ('ilove-mineraly', 'Íly a ílové minerály (zeolit, rašelina, humínové látky)', 'vitaminy_mineraly', 'pomenovana', '{}'::text[], false, false, 'Prírodné látky, ktoré viažu toxíny a pomáhajú pri trávení a pevnej stolici.', 70, 106, '1.0'),
  ('psenicny-lepok', 'Pšeničný lepok', 'obilnina', 'spracovana', '{obilniny}'::text[], false, false, 'Bielkovina z pšenice. Lacne zvyšuje obsah bielkovín na etikete; pre psy citlivé na lepok nevhodná.', 35, 59, '1.0'),
  ('obilniny-nespecifikovane', 'Obilniny (bez uvedenia druhu)', 'obilnina', 'nespecifikovana', '{obilniny}'::text[], false, false, 'Obilniny bez uvedenia, o ktoré ide. Výrobca môže ich zloženie meniť podľa ceny suroviny.', 30, 101, '1.0'),
  ('maso-nespecifikovane', 'Mäso / mäsová múčka bez uvedenia zvieraťa', 'zivocisny_vedlajsi_produkt', 'nespecifikovana', '{}'::text[], false, false, 'Mäso alebo múčka bez uvedenia, z akého zvieraťa pochádza. Pri alergii sa nedá overiť a nie je jasná ani kvalita surovín.', 20, 206, '1.0'),
  ('rastlinne-vedlajsie-produkty', 'Vedľajšie produkty rastlinného pôvodu', 'ine', 'nespecifikovana', '{}'::text[], false, false, 'Zvyšky zo spracovania rastlín bez bližšieho určenia. Nevieme, čo presne obsahuje.', 15, 82, '1.0'),
  ('oleje-a-tuky', 'Oleje a tuky (bez uvedenia zdroja)', 'tuk_olej', 'nespecifikovana', '{}'::text[], false, false, 'Zmes tukov a olejov bez uvedenia, či sú živočíšne alebo rastlinné a z čoho. Výrobca tak môže meniť suroviny bez zmeny etikety.', 20, 140, '1.0'),
  ('kozie-susene', 'Kozie mäso (sušené)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Sušené (dehydrované) kozie mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse.', 100, 2, '1.0'),
  ('zivocisne-vedlajsie-produkty', 'Živočíšne vedľajšie produkty / deriváty', 'zivocisny_vedlajsi_produkt', 'nespecifikovana', '{}'::text[], false, false, 'Súhrnné označenie pre časti zvierat, ktoré nie sú svalovinou (môžu to byť vnútornosti, ale aj menej hodnotné časti). Etiketa neuvádza, z akého zvieraťa ani z akých častí – nedá sa overiť, čo pes naozaj je.', 15, 129, '1.0'),
  ('vitaminy', 'Vitamíny / aminokyseliny', 'vitaminy_mineraly', 'pomenovana', '{}'::text[], false, false, 'Doplnené vitamíny alebo aminokyseliny, ktoré zabezpečujú kompletnú výživu.', 90, 436, '1.0'),
  ('kacacie-susene', 'Kačacie mäso (sušené)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Sušené (dehydrované) kačacie mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse.', 100, 38, '1.0'),
  ('psyllium', 'Psyllium (skorocel)', 'vlaknina', 'pomenovana', '{}'::text[], false, false, 'Rozpustná vláknina, ktorá reguluje trávenie a stolicu.', 85, 177, '1.0'),
  ('yucca', 'Yucca schidigera', 'prisada', 'pomenovana', '{}'::text[], false, false, 'Výťažok z rastliny yucca – znižuje zápach stolice a podporuje trávenie.', 88, 542, '1.0'),
  ('zverina-susene', 'Zverina mäso (sušené)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Sušené (dehydrované) zverina mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse.', 100, 9, '1.0'),
  ('biela-morska-ryba-susene', 'Biela morská ryba mäso (sušené)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Sušené (dehydrované) biela morská ryba mäso – konkrétne pomenovaný a koncentrovaný zdroj živočíšnych bielkovín. Percento na obale tu zodpovedá skutočnému podielu v granule lepšie ako pri čerstvom mäse.', 100, 22, '1.0'),
  ('biela-morska-ryba-cerstve', 'Biela morská ryba mäso (čerstvé)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Čerstvé biela morská ryba mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Pozor: čerstvé mäso obsahuje asi 70 % vody, takže po vysušení ho v granule zostane podstatne menej, než ukazuje percento na obale.', 100, 8, '1.0'),
  ('morske-plody-maso', 'Morské plody mäso', 'maso', 'pomenovana', '{}'::text[], false, false, 'Morské plody mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín.', 100, 18, '1.0'),
