  ('ine-obilniny', 'Proso / cirok / špalda / pohánka / quinoa', 'obilnina', 'pomenovana', '{obilniny}'::text[], false, false, 'Menej bežná obilnina alebo pseudoobilnina – zdroj energie a vlákniny.', 75, 219, '1.0'),
  ('kuracie-hydrolyz', 'Kuracie hydrolyzovaná bielkovina', 'maso', 'spracovana', '{kuracie}'::text[], false, false, 'Hydrolyzovaná kuracie bielkovina – bielkovina rozložená na menšie časti, ľahko stráviteľná a menej alergizujúca. Zdroj je pomenovaný. Kuracie je kvalitné mäso, ale patrí medzi častejšie alergény u psov.', 85, 122, '1.0'),
  ('biela-morska-ryba-maso', 'Biela morská ryba mäso', 'maso', 'pomenovana', '{}'::text[], false, false, 'Biela morská ryba mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín.', 100, 8, '1.0'),
