  ('makrela-cerstve', 'Makrela mäso (čerstvé)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Čerstvé makrela mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Pozor: čerstvé mäso obsahuje asi 70 % vody, takže po vysušení ho v granule zostane podstatne menej, než ukazuje percento na obale.', 100, 1, '1.0'),
  ('tuniak-cerstve', 'Tuniak mäso (čerstvé)', 'maso', 'pomenovana', '{}'::text[], false, false, 'Čerstvé tuniak mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín. Pozor: čerstvé mäso obsahuje asi 70 % vody, takže po vysušení ho v granule zostane podstatne menej, než ukazuje percento na obale.', 100, 1, '1.0'),
  ('autolyzat', 'Autolyzát (bez uvedenia zdroja)', 'prisada', 'nespecifikovana', '{}'::text[], false, false, 'Produkt samovoľného rozkladu bielkovín (napr. kvasníc alebo mäsa), slúži na zlepšenie chuti. Zdroj nie je uvedený.', 45, 18, '1.0'),
  ('tuniak-muck', 'Tuniak múčka', 'maso', 'spracovana', '{}'::text[], false, false, 'Múčka z tuniak mäsa – mäso (často aj s kosťami) usušené a zomleté. Pomenovaný a koncentrovaný zdroj bielkovín, no kvalita závisí od toho, aké časti zvieraťa sa použili.', 40, 5, '1.0'),
  ('platesa-maso', 'Platesa mäso', 'maso', 'pomenovana', '{}'::text[], false, false, 'Platesa mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín.', 100, 1, '1.0'),
  ('kozie-tuk', 'Kozie tuk / olej', 'tuk_olej', 'pomenovana', '{}'::text[], false, false, 'Kozie tuk / olej – pomenovaný zdroj energie a mastných kyselín.', 85, 1, '1.0'),
  ('hovadzie-hydrolyz', 'Hovädzie hydrolyzovaná bielkovina', 'maso', 'spracovana', '{}'::text[], false, false, 'Hydrolyzovaná hovädzie bielkovina – bielkovina rozložená na menšie časti, ľahko stráviteľná a menej alergizujúca. Zdroj je pomenovaný.', 85, 1, '1.0'),
  ('zverina-vnutor', 'Zverina vnútornosti', 'maso', 'pomenovana', '{}'::text[], false, false, 'Zverina vnútornosti (pečeň, srdce, žalúdky…) – pomenované a výživovo veľmi hodnotné, prirodzene bohaté na vitamíny a minerály.', 97, 3, '1.0'),
  ('prepelicie-vnutor', 'Prepeličie vnútornosti', 'maso', 'pomenovana', '{}'::text[], false, false, 'Prepeličie vnútornosti (pečeň, srdce, žalúdky…) – pomenované a výživovo veľmi hodnotné, prirodzene bohaté na vitamíny a minerály.', 97, 2, '1.0'),
  ('tuniak-maso', 'Tuniak mäso', 'maso', 'pomenovana', '{}'::text[], false, false, 'Tuniak mäso – konkrétne pomenovaný zdroj živočíšnych bielkovín.', 100, 1, '1.0'),
  ('kralicie-hydrolyz', 'Králičie hydrolyzovaná bielkovina', 'maso', 'spracovana', '{}'::text[], false, false, 'Hydrolyzovaná králičie bielkovina – bielkovina rozložená na menšie časti, ľahko stráviteľná a menej alergizujúca. Zdroj je pomenovaný.', 85, 1, '1.0'),
  ('kozie-bielkov', 'Kozie bielkovina', 'maso', 'spracovana', '{}'::text[], false, false, 'Kozie bielkovina / proteín – koncentrovaný a pomenovaný živočíšny zdroj bielkovín (sušené a odtučnené mäso).', 90, 2, '1.0'),
  ('konske-tuk', 'Konské tuk / olej', 'tuk_olej', 'pomenovana', '{}'::text[], false, false, 'Konské tuk / olej – pomenovaný zdroj energie a mastných kyselín.', 85, 1, '1.0')
